func:
// ② 규칙 평가가 매 분 통과하는 지점에서 서버에 심박을 보낸다.
// 이 노드로 msg 가 왔다는 것 = 이번 분 평가 사이클이 실제로 돌았다는 뜻.
// (fn_load_rules 는 같은 분 재실행이면 null 을 반환해 여기로 안 온다 → 매 분 1회)
var serverUrl = env.get('SERVER_URL') || global.get('pcServerUrl') || 'https://api.smartgreen.kr';
var farmId = env.get('FARM_ID') || global.get('farmId') || 'farm_0001';
var rules = global.get('automationRules') || [];
return {
    method: 'POST',
    url: serverUrl + '/internal/automation-heartbeat',
    headers: { 'Content-Type': 'application/json', 'x-api-key': env.get('SENSOR_API_KEY') || global.get('sensorApiKey') || '' },
    payload: { farmId: farmId, rulesCount: rules.length, houses: Object.keys(msg.allSensorData || {}).length },
    requestTimeout: 8000
};
